const { mkdtempSync, mkdirSync, writeFileSync, rmSync } = await import('fs');
const { tmpdir } = await import('os');
const { join } = await import('path');
const { execFileSync } = await import('child_process');
const dir = mkdtempSync(join(tmpdir(), 'koala-impl-review-'));
try {
  mkdirSync(join(dir, 'docs', 'story', 'actives'), { recursive: true });
  mkdirSync(join(dir, 'docs', 'requirements'), { recursive: true });
  writeFileSync(join(dir, 'koala.config.json'), JSON.stringify({ scanRoot:'packages/main', rootDir:'src', outDir:'packages/main/dist', testsDir:'packages/main/tests', fixturesDir:'packages/main/tests/fixtures', storyDir:'docs/story/actives', requirementsDir:'docs/requirements', storyPrefix:'B' }, null, 2));
  const cli = $root + '/packages/main/dist/cli.js';
  const created = execFileSync('node', [cli, '--root', dir, 'story_create', JSON.stringify({ name:'impl-review', title:'Impl review', description:'tmp', type:'feature', priority:'medium', checklist:[{ title:'x', context:'x' }] })], { cwd:$root, encoding:'utf8', stdio:['pipe','pipe','pipe'] });
  const storyId = created.match(/B-[a-f0-9]+/)?.[0];
  execFileSync('node', [cli, '--root', dir, 'implementation_review_result_set', JSON.stringify({ storyId, verdict:'fail', findings:[{ file:'src/foo.ts', line:42, why:'missing null guard', severity:'medium' }], summary:'implementation review found one issue' })], { cwd:$root, encoding:'utf8', stdio:['pipe','pipe','pipe'] });
  const raw = execFileSync('node', [cli, '--root', dir, 'implementation_review_result_get', JSON.stringify({ storyId })], { cwd:$root, encoding:'utf8', stdio:['pipe','pipe','pipe'] });
  const data = JSON.parse(raw.slice(raw.indexOf('{')));
  return { verdict: data.verdict === 'fail', findings: data.findings.length === 1, fileOk: data.findings[0].file === 'src/foo.ts' };
} finally { rmSync(dir, { recursive: true, force: true }); }

